style.css:
:root {
    -weed-green: #2ecc71;
    -lime-glow: #7CFF00;
    -dark-green: #145a32;
    -deep-black: #0c0f0d;
    -soft-black: #151a17;
    -ash-text: #d8fbe6;
  }

  /* Base */
  html, body {
    background-color: var(--deep-black) !important;
    color: var(--ash-text) !important;
  }

  /* Text */
  h1, h2, h3, h4, h5 {
    color: var(--lime-glow) !important;
    text-shadow: 0 0 8px rgba(124, 255, 0, 0.6);
  }

  p, span, li, label {
    color: var(--ash-text) !important;
  }

  /* Links */
  a {
    color: var(--weed-green) !important;
  }

  a:hover {
    color: var(--lime-glow) !important;
    text-shadow: 0 0 6px var(--lime-glow);
  }

  /* Containers / Cards */
  div, section, article, main, aside {
    background-color: var(--soft-black) !important;
    border-color: var(--dark-green) !important;
  }

  /* Inputs */
  input, textarea, select {
    background-color: #101410 !important;
    color: var(--ash-text) !important;
    border: 1px solid var(--dark-green) !important;
    border-radius: 8px;
  }

  input:focus, textarea:focus {
    outline: none !important;
    box-shadow: 0 0 10px rgba(46, 204, 113, 0.8);
  }

  /* Buttons */
  button, input[type="submit"] {
    background: linear-gradient(135deg, var(--weed-green), var(--dark-green)) !important;
    color: #041b0f !important;
    border: none !important;
    border-radius: 999px;
    padding: 8px 18px;
    font-weight: 600;
    box-shadow: 0 0 12px rgba(46, 204, 113, 0.6);
  }

  button:hover, input[type="submit"]:hover {
    box-shadow: 0 0 25px rgba(124, 255, 0, 0.9);
    transform: scale(1.05);
  }

  /* Scrollbar (WebKit browsers) */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #0b0f0c;
  }

  ::-webkit-scrollbar-thumb {
    background: linear-gradient(var(--dark-green), var(--weed-green));
    border-radius: 10px;
  }

  /* Subtle smoky overlay */
  body::after {
    content: "";
    position: fixed;
    inset: 0;
    background: radial-gradient(
      circle at top,
      rgba(46, 204, 113, 0.08),
      transparent 70%
    );
    pointer-events: none;
    z-index: 9999;
  }
